        next_state = 1;
    else if (state == 0 && new_data == 0)
        next_state = 0;
    else if (state == 1 && fscts == 1)
        next_state = 2;
    else if (state == 1 && fscts == 0)
        next_state = 1;
    else if (state == 2 && bit_position == 9)
        next_state = 0;
    else if (state == 2 && bit_position != 9)
        next_state = 2;
    else
